Here is the commit message:
nexthop: fix IPv6 route referencing IPv4 nexthop

syzbot reported a panic [1] [2].

When an IPv6 nexthop is replaced with an IPv4 nexthop, the has_v4 flag
of all groups containing this nexthop is not updated. This is because
nh_group_v4_update is only called when replacing AF_INET to AF_INET6,
but the reverse direction (AF_INET6 to AF_INET) is missed.

This allows a stale has_v4=false to bypass fib6_check_nexthop, causing
IPv6 routes to be attached to groups that effectively contain only AF_INET
members. Subsequent route lookups then call nexthop_fib6_nh() which
returns NULL for the AF_INET member, leading to a NULL pointer
dereference.

Fix by calling nh_group_v4_update whenever the family changes, not just
AF_INET to AF_INET6.

Reproducer:
	# AF_INET6 blackhole
	ip -6 nexthop add id 1 blackhole
	# group with has_v4=false
	ip nexthop add id 100 group 1
	# replace with AF_INET (no -6), has_v4 stays false
	ip nexthop replace id 1 blackhole
	# pass stale has_v4 check
	ip -6 route add 2001:db8::/64 nhid 100
	# panic
	ping -6 2001:db8::1

[1] https://syzkaller.appspot.com/bug?id=e17283eb2f8dcf3dd9b47fe6f67a95f71faadad0
[2] https://syzkaller.appspot.com/bug?id=8699b6ae54c9f35837d925686208402949e12ef3
Fixes: 7bf4796dd099 ("nexthops: add support for replace")
Signed-off-by: Jiayuan Chen <jiayuan.chen@linux.dev>
Reviewed-by: David Ahern <dsahern@kernel.org>
Link: https://patch.msgid.link/20260413114522.147784-1-jiayuan.chen@linux.dev
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The `replace_nexthop_single()` function in `net/ipv4/nexthop.c` only updates the `has_v4` flag of groups when replacing an IPv4 nexthop with an IPv6 nexthop, but misses the reverse case of replacing an IPv6 nexthop with an IPv4 nexthop. This leaves the group's `has_v4` flag stale (`false` even though all members are now IPv4), allowing IPv6 routes to be incorrectly attached to such groups. During route lookup, `nexthop_fib6_nh()` returns `NULL` for IPv4-only members, causing a NULL pointer dereference.

Here is the patch:

 static int replace_nexthop_single(struct net *net, struct nexthop *old,
 				  struct nexthop *new,
 				  struct netlink_ext_ack *extack)
 {
 	u8 old_protocol, old_nh_flags;
 	struct nh_info *oldi, *newi;
 	struct nh_grp_entry *nhge;
 	int err;

 	if (new->is_group) {
 		NL_SET_ERR_MSG(extack, "Can not replace a nexthop with a nexthop group.");
 		return -EINVAL;
 	}

 	if (!list_empty(&old->grp_list) &&
 	    rtnl_dereference(new->nh_info)->fdb_nh !=
 	    rtnl_dereference(old->nh_info)->fdb_nh) {
 		NL_SET_ERR_MSG(extack, "Cannot change nexthop FDB status while in a group");
 		return -EINVAL;
 	}

 	err = call_nexthop_notifiers(net, NEXTHOP_EVENT_REPLACE, new, extack);
 	if (err)
 		return err;

 	/* Hardware flags were set on 'old' as 'new' is not in the red-black
 	 * tree. Therefore, inherit the flags from 'old' to 'new'.
 	 */
 	new->nh_flags |= old->nh_flags & (RTNH_F_OFFLOAD | RTNH_F_TRAP);

 	oldi = rtnl_dereference(old->nh_info);
 	newi = rtnl_dereference(new->nh_info);

 	newi->nh_parent = old;
 	oldi->nh_parent = new;

 	old_protocol = old->protocol;
 	old_nh_flags = old->nh_flags;

 	old->protocol = new->protocol;
 	old->nh_flags = new->nh_flags;

 	rcu_assign_pointer(old->nh_info, newi);
 	rcu_assign_pointer(new->nh_info, oldi);

 	/* Send a replace notification for all the groups using the nexthop. */
 	list_for_each_entry(nhge, &old->grp_list, nh_list) {
 		struct nexthop *nhp = nhge->nh_parent;

 		err = replace_nexthop_single_notify(net, nhp, old, oldi, newi,
 						    extack);
 		if (err)
 			goto err_notify;
 	}

-	/* When replacing an IPv4 nexthop with an IPv6 nexthop, potentially
+	/* When replacing a nexthop with one of a different family, potentially
 	 * update IPv4 indication in all the groups using the nexthop.
 	 */
-	if (oldi->family == AF_INET && newi->family == AF_INET6) {
+	if (oldi->family != newi->family) {
 		list_for_each_entry(nhge, &old->grp_list, nh_list) {
 			struct nexthop *nhp = nhge->nh_parent;
 			struct nh_group *nhg;

 			nhg = rtnl_dereference(nhp->nh_grp);
 			nh_group_v4_update(nhg);
 		}
 	}

 	return 0;

 err_notify:
 	rcu_assign_pointer(new->nh_info, newi);
 	rcu_assign_pointer(old->nh_info, oldi);
 	old->nh_flags = old_nh_flags;
 	old->protocol = old_protocol;
 	oldi->nh_parent = old;
 	newi->nh_parent = new;
 	list_for_each_entry_continue_reverse(nhge, &old->grp_list, nh_list) {
 		struct nexthop *nhp = nhge->nh_parent;

 		replace_nexthop_single_notify(net, nhp, old, newi, oldi, NULL);
 	}
 	call_nexthop_notifiers(net, NEXTHOP_EVENT_REPLACE, old, extack);
 	return err;
 }



